def check_brackets(expression):
    stack = []
    brackets_map = {"(": ")", "[": "]", "{": "}"}
    for char in expression:
        if char in brackets_map.keys():
            stack.append(char)
        elif char in brackets_map.values():
            if len(stack) == 0 or brackets_map[stack.pop()] != char:
                return False
    return len(stack) == 0
