def letter_count(input_string):
    # 创建一个空字典来储存计数器
    counter = {}
    # 遍历字符串中的每个字符
    for letter in input_string:
        # 如果字母不在计数器中，则将其添加到计数器中并将值设置为1
        if letter not in counter:
            counter[letter] = 1
        # 如果字母已经在计数器中，则将其值加1
        else:
            counter[letter] += 1
    # 返回计数器
    return counter
```
