def first_unique_char(string):
    # 创建一个dict来存储每个字符出现的次数
    char_count = {}
    for char in string:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    # 找到第一个只出现一次的字符，并返回其索引值
    for index, char in enumerate(string):
        if char_count[char] == 1:
            return index
