```
function getValueByPath(obj, path) {
  // 将路径拆分为各个部分
  const parts = path.split(".");
  // 初始化一个变量来保存当前值
  // 将其设置为初始对象
  let value = obj;
  // 遍历路径的每个部分
  for (const part of parts) {
    // 更新值为当前字段的值
    value = value[part];
    // 如果值为undefined，则返回undefined
    // （路径不存在于对象中）
    if (value === undefined) {
      return undefined;
    }
  }
  // 返回最终值
  return value;
}
```
